/* Tatar Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Guzel": "beautiful — Turkic", "Timur": "iron — Turkic temur", "Aygul": "moon flower — Turkic ay + gul", "Rinat": "reborn — Latin renatus, via Russian", "Alsu": "A popular feminine name in Tatarstan.", "Marat": "A widely used masculine name among Tatars.", "Nureyev": "Family name of Rudolf Nureyev, the legendary Tatar ballet dancer.", "Shaymiyev": "Family name of Mintimer Shaymiyev, first president of Tatarstan.", "Minnikhanov": "Family name of Rustam Minnikhanov, president of Tatarstan.", "Akhmetov": "A common Tatar surname from Akhmet."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Guzel';
console.log(lookup(q));

